import {lessonById,type SiteLesson} from './lessons';
import type {Faq} from './safety';
import {scene,type RawScene,type Scene} from './scenes';
/**
 * The GLOSSARY (SEO cluster 2, Nov 10 2026): /learn/soccer-terms with every term on one page in A-Z sections, and a page of
 * its own under /learn/soccer-terms/<slug> only for the terms people search for and that can carry a diagram and 250+ useful
 * words. All words live here; the two routes only render.
 *
 * SOURCES (checked Nov 10 2026):
 *  - Wording first from the repo: lib/learning/conceptMap.ts (one-two / wall pass, third-man, overlap and underlap, switch of
 *    play, support angle, width, 2v1, press and cover, goal side, win it / lose it, through ball, cut-back, far post, pivot) and
 *    the lessons those concepts point to in public/lessons/*.json (s_onetwo, learn9_wall, f_pared, e_thirdman, next7_outsideback,
 *    e_switch, learn9_switch, learn9_two_one, def_7_goalside, def_11_pressurecover, trn_9_firstpass, learn11_cutback …).
 *    Every lesson id is checked against the catalog when this module loads.
 *  - Words that are rules are defined from the Laws exactly as on the rule pages (sources in lib/site/rules.ts): IFAB Laws 1,
 *    2, 3, 4 (shinguards are compulsory equipment), 5 (VAR, advantage), 7 (stoppage time), 8, 10 (extra time: two periods of
 *    no more than 15 minutes; penalty shoot-out), 11-17; FIFA Futsal Laws 2025-26; U.S. Soccer and US Youth Soccer standards.
 *  - Museum data (lib/endgame/museum.ts) for "kit", "boots" and the video assistant referee (exhibit var-2018).
 *  - Everyday soccer words (assist, brace, clean sheet, hat-trick, nutmeg, nil, derby-style slang is left out) are defined by
 *    their plain meaning only. No word origins, no records, no statistics and no named players: none of that was verified.
 */
export type TermPage={slug:string;path:string;name:string;also?:string;title:string;h1:string;desc:string;short:string;answer:string;scene:Scene;picture:string;how:string[];howTitle:string;
 mistakes:string[];formats:string;faq:Faq[];lessons:SiteLesson[];cta?:SiteLesson;related:string[]};
export type GlossaryEntry={term:string;id:string;def:string;to?:string;toName?:string};
export const TERMS_HUB_PATH='/learn/soccer-terms';
export const termPath=(slug:string)=>`${TERMS_HUB_PATH}/${slug}`;
const pick=(ids:string[])=>ids.map(id=>{const l=lessonById(id);if(!l)throw new Error(`glossary lesson ${id} is not in the lesson catalog`);return l;});
type Raw=Omit<TermPage,'path'|'scene'|'lessons'|'cta'|'picture'|'title'|'h1'>&{scene:RawScene;lessonIds:string[];title?:string;h1?:string};
const make=({scene:sc,lessonIds,...t}:Raw):TermPage=>{const lessons=pick(lessonIds);
 return {...t,title:t.title??`What Is ${/^[aeiou]/i.test(t.name)?'an':'a'} ${t.name} in Soccer? For Kids`,h1:t.h1??`What is ${/^[aeiou]/i.test(t.name)?'an':'a'} ${t.name.toLowerCase()} in soccer?`,path:termPath(t.slug),scene:scene(sc),picture:`${t.slug}-term.png`,lessons,cta:lessons[0]};};

